const purgeFinishedFlowRuns = `-- name: PurgeFinishedFlowRuns :execrows
DELETE FROM flow_runs
WHERE status <> 'running'
  AND finished_at < ?1
`

func (q *Queries) PurgeFinishedFlowRuns(ctx context.Context, before *int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, purgeFinishedFlowRuns, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const purgeFinishedTasks = `-- name: PurgeFinishedTasks :execrows

DELETE FROM tasks
WHERE status IN ('succeeded', 'canceled', 'dead')
  AND finished_at < ?1
  AND flow_run_id IS NULL
`

// =====================================================================
// Housekeeping
// =====================================================================
// PurgeFinishedTasks: delete terminal standalone tasks older than a cutoff
// (attempts and events go with them via ON DELETE CASCADE).
func (q *Queries) PurgeFinishedTasks(ctx context.Context, before *int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, purgeFinishedTasks, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const reapExpiredLeases = `-- name: ReapExpiredLeases :many

UPDATE tasks
SET status       = CASE WHEN attempt >= max_attempts THEN 'dead' ELSE 'retry' END,
    run_at       = CAST(?1 AS INTEGER),
    finished_at  = CASE WHEN attempt >= max_attempts THEN CAST(?1 AS INTEGER) ELSE NULL END,
    last_error   = 'lease expired (worker ' || locked_by || ')',
    locked_by    = NULL,
    locked_until = NULL,
    version      = version + 1,
    updated_at   = CAST(?1 AS INTEGER)
WHERE status = 'running'
  AND locked_until < CAST(?1 AS INTEGER)
RETURNING id, attempt, status
`

type ReapExpiredLeasesRow struct {
	ID      int64  `json:"id"`
	Attempt int64  `json:"attempt"`
	Status  string `json:"status"`
}

// =====================================================================
// Crash recovery (run periodically, e.g. every few seconds, by one reaper)
// =====================================================================
// ReapExpiredLeases: running tasks whose worker vanished. They go back to
// retry (claimable now) or to dead when out of attempts. Follow with
// TimeoutAttempts for each returned row, in the same transaction.
func (q *Queries) ReapExpiredLeases(ctx context.Context, now int64) ([]ReapExpiredLeasesRow, error) {
	rows, err := q.db.QueryContext(ctx, reapExpiredLeases, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReapExpiredLeasesRow{}
	for rows.Next() {
		var i ReapExpiredLeasesRow
		if err := rows.Scan(&i.ID, &i.Attempt, &i.Status); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const requeueTask = `-- name: RequeueTask :execrows
UPDATE tasks
SET status       = 'pending',
    max_attempts = attempt + ?1,
    run_at       = CAST(?2 AS INTEGER),
    last_error   = NULL,
    finished_at  = NULL,
    version      = version + 1,
    updated_at   = CAST(?2 AS INTEGER)
WHERE id = ?3
  AND status IN ('dead', 'canceled')
`

type RequeueTaskParams struct {
	ExtraAttempts int64 `json:"extra_attempts"`
	Now           int64 `json:"now"`
	ID            int64 `json:"id"`
}

// RequeueTask: manual retry of a dead/canceled task. Attempt history is kept;
// the budget is extended by extra_attempts instead of resetting the counter.
func (q *Queries) RequeueTask(ctx context.Context, arg RequeueTaskParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueTask, arg.ExtraAttempts, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const startAttempt = `-- name: StartAttempt :one
INSERT INTO task_attempts (task_id, attempt, worker_id, started_at)
VALUES (?1, ?2, CAST(?3 AS TEXT), CAST(?4 AS INTEGER))
RETURNING id, task_id, attempt, worker_id, status, error, result, started_at, finished_at, duration_ms
`

type StartAttemptParams struct {
	TaskID   int64  `json:"task_id"`
	Attempt  int64  `json:"attempt"`
	WorkerID string `json:"worker_id"`
	Now      int64  `json:"now"`
}

func (q *Queries) StartAttempt(ctx context.Context, arg StartAttemptParams) (TaskAttempt, error) {
	row := q.db.QueryRowContext(ctx, startAttempt,
		arg.TaskID,
		arg.Attempt,
		arg.WorkerID,
		arg.Now,
	)
	var i TaskAttempt
	err := row.Scan(
		&i.ID,
		&i.TaskID,
		&i.Attempt,
		&i.WorkerID,
		&i.Status,
		&i.Error,
		&i.Result,
		&i.StartedAt,
		&i.FinishedAt,
		&i.DurationMs,
	)
	return i, err
}

const timeoutAttempt = `-- name: TimeoutAttempt :exec
UPDATE task_attempts
SET status      = 'timed_out',
    error       = 'lease expired',
    finished_at = CAST(?1 AS INTEGER)
WHERE task_id = ?2
  AND attempt = ?3
  AND status = 'running'
`

type TimeoutAttemptParams struct {
	Now     int64 `json:"now"`
	TaskID  int64 `json:"task_id"`
	Attempt int64 `json:"attempt"`
}

func (q *Queries) TimeoutAttempt(ctx context.Context, arg TimeoutAttemptParams) error {
	_, err := q.db.ExecContext(ctx, timeoutAttempt, arg.Now, arg.TaskID, arg.Attempt)
	return err
}
